// clang-format off
// This test verifies that a cross-team reduction kernel is generated by
// default and that the thread_limit clause is honored verbatim. The block size
// is used as requested, it is not rounded to a power of 2.
//
// RUN: %libomptarget-compile-generic
// RUN: env LIBOMPTARGET_INFO=16 %libomptarget-run-generic 2>&1 | %fcheck-generic

// UNSUPPORTED: nvptx64-nvidia-cuda
// UNSUPPORTED: nvptx64-nvidia-cuda-LTO
// UNSUPPORTED: aarch64-unknown-linux-gnu
// UNSUPPORTED: aarch64-unknown-linux-gnu-LTO
// UNSUPPORTED: x86_64-unknown-linux-gnu
// UNSUPPORTED: x86_64-unknown-linux-gnu-LTO

// clang-format on
#include <stdio.h>

int main() {
  int N = 100;

  double a[N];

  for (int i = 0; i < N; i++)
    a[i] = i;

  double sum1;
  sum1 = 0;

#pragma omp target teams distribute parallel for reduction(+ : sum1) thread_limit(130)
  for (int j = 0; j < N; j = j + 1)
    sum1 += a[j];

  int rc = sum1 != 4950;

  if (!rc)
    printf("Success\n");

  return rc;
}
// clang-format off
/// CHECK: Launching kernel {{.*}} with [1,1,1] blocks and [130,1,1] threads in SPMD mode
/// CHECK: Success

